import { icon, escapeHtml, avatar } from './ui.js';

export const DEPENDENT_ROUTES = ['dependents'];
const escape = escapeHtml;
const name = person => person?.name || [person?.firstName, person?.lastName].filter(Boolean).join(' ');
const initials = person => [person?.firstName, person?.lastName].filter(Boolean).map(value => value[0]).join('').slice(0, 2) || name(person)?.[0] || 'D';
const symbol = person => `<span class="dependent-avatar" aria-hidden="true">${escape(initials(person))}</span>`;

export function renderDependents(route, state) {
  if (route !== 'dependents') return null;
  const list = state.dependents || [], groupId = state.dependentsReturnGroupId;
  const back = groupId ? `group?id=${encodeURIComponent(groupId)}` : 'dashboard';
  return `<section class="dependents-page"><a class="group-back" href="#${back}" data-route="${back}">${icon('arrow-left', 16)} ${groupId ? 'Voltar para o grupo' : 'Meus grupos'}</a><div class="dependents-heading"><span class="eyebrow">TEM LUGAR PARA TODO MUNDO</span><h1>Meus dependentes<span>.</span></h1><p>Cadastre quem participa com você, sem precisar de e-mail ou conta própria.</p></div>${groupId ? `<div class="dependents-return-note">${icon('info', 19)}<p>Depois do cadastro, você volta ao grupo para escolher se este dependente participa do sorteio.</p></div>` : ''}<div class="dependents-layout"><section class="panel dependents-list-panel"><div class="dependents-panel-heading"><span class="dependents-heading-symbol">${icon('users', 23)}</span><div><h2>Sua turma de perto <span>${list.length}</span></h2><p>Você acompanha os resultados dessas pessoas.</p></div></div>${list.length ? `<ul class="dependents-catalog">${list.map(dependent => `<li>${symbol(dependent)}<div><strong>${escape(name(dependent))}</strong><span>Sob sua responsabilidade</span></div>${icon('heart', 17)}</li>`).join('')}</ul>` : `<div class="dependents-empty"><span>${icon('heart', 29)}</span><h3>Uma pequena pessoa.<br>Uma grande surpresa.</h3><p>Cadastre seu primeiro dependente. Você escolhe em quais grupos ele participa.</p></div>`}<div class="dependents-list-note">${icon('shield', 17)}<p>Cadastrar não inclui a pessoa automaticamente nos grupos. A participação é escolhida em cada amigo secreto.</p></div></section><form class="panel dependents-create-form" data-form="create-dependent"><span class="eyebrow">UM NOME PARA A BRINCADEIRA</span><h2>Adicionar dependente</h2><p>Como sua turma conhece essa pessoa?</p><label class="field" for="dependent-first-name">Nome<input id="dependent-first-name" name="firstName" required maxlength="80" autocomplete="off" placeholder="Nome do dependente"></label><label class="field" for="dependent-last-name">Sobrenome<input id="dependent-last-name" name="lastName" required maxlength="120" autocomplete="off" placeholder="Sobrenome do dependente"></label><div class="dependents-no-email">${icon('check-circle', 17)} Não precisa de e-mail nem de senha.</div><button type="submit" class="btn btn-primary btn-block">${icon('plus', 18)} Adicionar dependente</button><p class="dependents-create-footnote">Os avisos e resultados ficam com você, na sua conta e no seu e-mail.</p></form></div></section>`;
}

export function renderGroupDependents(state) {
  if (!state.production || !state.group?.id) return '';
  const list = state.ownDependents || [], active = list.filter(dependent => dependent.active), locked = state.drawn;
  const catalogRoute = `dependents?group=${encodeURIComponent(state.group.id)}`;
  return `<section class="panel group-dependents" aria-labelledby="group-dependents-title"><div class="group-dependents-heading"><div><span class="eyebrow">QUEM PARTICIPA COM VOCÊ</span><h2 id="group-dependents-title">Seus dependentes neste grupo <span>${active.length}</span></h2><p>${locked ? 'O sorteio já foi realizado. As participações estão fechadas.' : 'Inclua quem vai brincar. Cada dependente ativo dá e recebe um presente no sorteio.'}</p></div>${locked ? `<span class="group-dependents-locked">${icon('lock', 16)} Sorteio realizado</span>` : `<a class="btn btn-secondary" href="#${catalogRoute}" data-route="${catalogRoute}">${icon('plus', 17)} Cadastrar dependente</a>`}</div>${state.dependentGroupError ? `<p class="dependents-group-error" role="alert">${escape(state.dependentGroupError)}</p>` : ''}${list.length ? `<ul class="group-dependents-list">${list.map(dependent => `<li>${symbol(dependent)}<div class="group-dependent-identity"><strong>${escape(name(dependent))}</strong><span>${dependent.active ? locked ? 'Participou deste sorteio' : 'Incluído neste grupo' : locked ? 'Não participou deste sorteio' : 'Fora deste grupo'}</span></div><span class="group-status group-status-${dependent.active ? 'green' : 'neutral'}">${dependent.active ? 'Participando' : 'Não incluído'}</span>${!locked ? `<button type="button" class="btn ${dependent.active ? 'btn-secondary' : 'btn-primary'}" data-action="toggle-dependent" data-dependent-id="${escape(dependent.id)}" data-dependent-active="${!dependent.active}" aria-label="${dependent.active ? 'Retirar' : 'Incluir'} ${escape(name(dependent))} ${dependent.active ? 'deste' : 'neste'} grupo" aria-pressed="${Boolean(dependent.active)}" aria-busy="${state.dependentBusyId === dependent.id}" ${state.dependentBusyId ? 'disabled' : ''}>${icon(state.dependentBusyId === dependent.id ? 'clock' : dependent.active ? 'x' : 'plus', 16)} ${state.dependentBusyId === dependent.id ? 'Salvando…' : dependent.active ? 'Retirar do grupo' : 'Incluir no grupo'}</button>` : ''}</li>`).join('')}</ul>` : `<div class="group-dependents-empty">${icon('users', 23)}<p>${locked ? 'Nenhum dependente seu participou deste sorteio.' : 'Ainda não há dependentes cadastrados. Você pode adicionar uma criança ou outra pessoa que participa sob sua responsabilidade.'}</p></div>`}<div class="group-dependents-note">${icon(locked ? 'lock' : 'info', 16)}<p>${locked ? 'Você consulta o resultado de cada dependente participante na página de revelação.' : 'Apenas quem estiver incluído no momento do sorteio participa. Você pode mudar essa escolha até o sorteio começar.'}</p></div></section>`;
}

export function renderDependentResults(state) {
  if (!state.revealed || !state.dependentResults?.length) return '';
  return `<section class="dependent-results" aria-labelledby="dependent-results-title"><div class="dependent-results-heading"><span>${icon('users', 22)}</span><div><h2 id="dependent-results-title">As surpresas dos seus dependentes</h2><p>Estes resultados ficam com você como responsável.</p></div></div><div class="dependent-results-grid">${state.dependentResults.map(({ dependent, match }) => `<article class="panel dependent-result-card"><div class="dependent-result-owner">${symbol(dependent)}<div><small>AMIGO SECRETO DE</small><h3>${escape(name(dependent))}</h3></div></div><div class="dependent-result-arrow">${icon('chevron-down', 20)} <span>vai presentear</span></div><div class="dependent-result-match">${avatar(match.name, 2, '', match.avatar ?? null)}<h3>${escape(match.name)}</h3><p>${match.isDependent || match.dependentId ? `Dependente · responsável: ${escape(match.responsibleName || 'uma pessoa do grupo')}` : escape(match.email || '')}</p></div><p class="dependent-result-note">${icon('gift', 15)} Um presente escolhido com carinho.</p></article>`).join('')}</div></section>`;
}
